<?php
require_once __DIR__.'/../invoices/issuance_snapshot_service.php';
function canonicalizeEInvoiceValue($value){if(is_array($value)){if(array_is_list($value)){return array_map('canonicalizeEInvoiceValue',$value);}ksort($value,SORT_STRING);foreach($value as $k=>$v)$value[$k]=canonicalizeEInvoiceValue($v);}return $value;}
function canonicalEInvoiceJson(array $payload):string{$json=json_encode(canonicalizeEInvoiceValue($payload),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRESERVE_ZERO_FRACTION);if($json===false)throw new Exception('Could not serialize electronic invoice payload');return $json;}
function requireEInvoice(mysqli $c,int $invoiceId,int $uid):array{$s=$c->prepare("SELECT i.* FROM erp_invoices i WHERE i.id=? AND i.user_id=? LIMIT 1");$s->bind_param('ii',$invoiceId,$uid);$s->execute();$r=$s->get_result()->fetch_assoc();$s->close();if(!$r||strtoupper((string)$r['invoice_type'])!=='FACTURE'||(int)$r['is_validated']!==1)throw new Exception('Only validated invoices can enter the electronic invoicing outbox');$snapshot=invoiceSnapshotLoad($c,$uid,$invoiceId)??captureInvoiceIssuanceSnapshot($c,$uid,$uid,$invoiceId);$seller=$snapshot['seller']??[];$buyer=$snapshot['buyer']??[];$r['organization_name']=(string)($seller['name']??'');$r['seller_fiscal_id']=(string)($seller['fiscal_id']??'');$r['seller_address']=(string)($seller['address']??'');$r['client_name']=(string)($buyer['name']??'');$r['client_fiscal_id']=(string)($buyer['fiscal_id']??'');$r['client_cin']=(string)($buyer['cin']??'');$r['client_address']=(string)($buyer['address']??'');$r['_issuance_snapshot']=$snapshot;if(trim((string)$r['seller_fiscal_id'])===''||trim((string)$r['seller_address'])===''||trim((string)$r['client_name'])===''||trim((string)$r['client_address'])===''||(trim((string)$r['client_fiscal_id'])===''&&trim((string)$r['client_cin'])===''))throw new Exception('Seller and customer fiscal identity must be complete before electronic invoicing');return $r;}
